from pathlib import Path
import sys,json,hashlib,shutil,html
import xml.etree.ElementTree as ET
base=Path('ProjectDocs/AI/CoreJourneyAudit/R1');run_name=sys.argv[1]
assert Path(run_name).name==run_name and run_name not in ('.','..')
run=Path('/tmp/lor-core-journey-r1')/run_name
result=ET.parse(run/'PlayMode/results.xml').getroot().attrib
assert result['result']=='Passed' and result['skipped']=='0',result
out=base/'UnityCaptures';out.mkdir(exist_ok=True)
for p in (run/'Journey').iterdir():shutil.copy2(p,out/p.name)
qa=base/'QA'/run_name/'PlayMode';qa.mkdir(parents=True,exist_ok=True)
for n in ['results.xml','command.json','unity.log','launcher.log']:shutil.copy2(run/'PlayMode'/n,qa/n)
before=json.loads((base/'Sources/AssetsBefore.json').read_text());after={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in Path('Assets').rglob('*') if p.is_file()}
scope={'tests':{k:result[k] for k in ('total','passed','failed','skipped')},'modified':[p for p,h in before.items() if p in after and after[p]!=h],'added':sorted(set(after)-set(before)),'deleted':sorted(set(before)-set(after)),'unchanged':sum(after.get(p)==h for p,h in before.items()),'nativeCaptures':len(list(out.glob('*.png'))),'journeys':[json.loads(p.read_text()) for p in sorted(out.glob('*_Result.json'))]}
(base/'QA/ScopeAndVerification.json').write_text(json.dumps(scope,indent=2)+'\n')
options=''.join('<option value="'+p.stem+'">'+html.escape(p.stem.replace('_',' '))+'</option>' for p in sorted(out.glob('*.png')))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Core Journey Audit R1</title><style>*{box-sizing:border-box}body{margin:0;background:#080e17;color:#e3d5b4;font:16px/1.5 system-ui}main{max-width:680px;margin:auto;padding:20px}h1{font:28px Georgia;color:#dabb79}a{color:#b5d1eb}select{width:100%;padding:12px;background:#122333;color:#eee;border:1px solid #7f693f;margin:8px 0 18px}img{display:block;width:100%;height:auto}.image-window{max-width:100%;overflow:auto}.native img{width:auto;max-width:none}button{padding:10px;margin:0 0 12px;background:#19304a;color:#eee;border:1px solid #7f693f}figure{margin:0 auto;max-width:470px}figcaption{font-size:13px;padding:12px 0;color:#c2bcae}</style><main><h1>Core Journey · Audit R1</h1><p>Actual Unity captures from continuous Russian victory and English failure/retry journeys. Visible controls are activated through native raycasts; legal board swipes trigger the real outcome callbacks and saved results. Pause, Settings, energy gating and the return through both maps are exercised.</p><p><a href="ImplementationReport.md">Report and limits</a> · <a href="QA/ScopeAndVerification.json">Verification</a></p><label for="view">Journey step (captured before the tap)</label><select id="view">OPTIONS</select><button id="zoom">View at native pixels</button><figure><div class="image-window" id="window"><img id="page" alt="Actual Unity core journey capture"></div><figcaption id="caption"></figcaption></figure><p>This viewer displays screenshots, not a playable game. Captures use a simulated 576×1280 phone with safe area. Tutorials are pre-completed in the isolated test save. No physical-device or backend testing.</p></main><script>const view=document.getElementById('view'),pic=document.getElementById('page');function show(){pic.src='UnityCaptures/'+view.value+'.png';document.getElementById('caption').textContent=view.selectedOptions[0].textContent+' — actual Unity capture';}view.onchange=show;document.getElementById('zoom').onclick=()=>{const on=document.getElementById('window').classList.toggle('native');document.getElementById('zoom').textContent=on?'Fit to page':'View at native pixels';};show();</script></html>'''
(base/'CoreJourney_Audit_R1_Review.html').write_text(page.replace('OPTIONS',options));print(json.dumps(scope,indent=2))
